import{_ as t,o as s,c as i,a5 as o}from"./chunks/framework.KOk-c1Ha.js";const p=JSON.parse('{"title":"Troubleshooting: Webhooks Not Arriving","description":"Diagnose why external webhooks are not producing Matrix messages","frontmatter":{"title":"Troubleshooting: Webhooks Not Arriving","description":"Diagnose why external webhooks are not producing Matrix messages","audience":["operator","user"],"symptoms":["no messages in room","webhook returns 200 but nothing happens","webhook returns 404"]},"headers":[],"relativePath":"troubleshooting/webhooks-not-arriving.md","filePath":"troubleshooting/webhooks-not-arriving.md","lastUpdated":1775242895000}'),a={name:"troubleshooting/webhooks-not-arriving.md"};function h(n,e,r,c,l,d){return s(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="webhooks-not-arriving" tabindex="-1">Webhooks Not Arriving <a class="header-anchor" href="#webhooks-not-arriving" aria-label="Permalink to &quot;Webhooks Not Arriving&quot;">​</a></h1><p>You configured a webhook but messages aren&#39;t appearing in your Matrix room. Work through these checks in order — most common causes first.</p><h2 id="check-1-is-hookshot-receiving-the-webhook" tabindex="-1">Check 1: Is hookshot receiving the webhook? <a class="header-anchor" href="#check-1-is-hookshot-receiving-the-webhook" aria-label="Permalink to &quot;Check 1: Is hookshot receiving the webhook?&quot;">​</a></h2><p>Send a test request and check the HTTP response:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://hookshot.example.com/{service}/webhook</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;test&quot;: true}&#39;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Response</th><th>Meaning</th><th>Next step</th></tr></thead><tbody><tr><td><code>200 {&quot;ok&quot;:true}</code></td><td>Hookshot received it</td><td>Problem is downstream — go to Check 2</td></tr><tr><td><code>404 Not Found</code></td><td>URL doesn&#39;t match any connection</td><td>Verify the URL path. For generic webhooks, check the hookId. For GitHub, the path should be <code>/github/webhook</code>.</td></tr><tr><td><code>401 Unauthorized</code></td><td>Signature/secret mismatch</td><td>Check webhook secret in config matches the service&#39;s settings</td></tr><tr><td><code>Connection refused</code></td><td>Hookshot not listening on that port</td><td>Verify hookshot is running. Check <code>listeners</code> config — webhooks need a listener with <code>resources: [webhooks]</code></td></tr><tr><td><code>502 / 503</code></td><td>Reverse proxy can&#39;t reach hookshot</td><td>Check your nginx/caddy config, ensure it proxies to the correct port</td></tr></tbody></table><h3 id="check-port-and-listener-config" tabindex="-1">Check port and listener config <a class="header-anchor" href="#check-port-and-listener-config" aria-label="Permalink to &quot;Check port and listener config&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># config.yml — webhooks must have a dedicated listener</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">listeners</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9000</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    bindAddress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0.0.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 0.0.0.0 for Docker, 127.0.0.1 for localhost-only</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    resources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">webhooks</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # This listener serves webhooks</span></span></code></pre></div><p>If running in Docker, verify the port is exposed and mapped correctly.</p><h2 id="check-2-is-the-connection-active" tabindex="-1">Check 2: Is the connection active? <a class="header-anchor" href="#check-2-is-the-connection-active" aria-label="Permalink to &quot;Check 2: Is the connection active?&quot;">​</a></h2><p>In the Matrix room, send:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!hookshot list</span></span></code></pre></div><p>This lists all connections in the room. Verify your integration appears.</p><p>If the connection is missing:</p><ul><li>Recreate it: <code>!hookshot github repo &lt;url&gt;</code> or <code>!hookshot webhook &lt;name&gt;</code></li><li>Check that the bot has permission to read room state (needs at least PL 0)</li></ul><h2 id="check-3-is-the-event-type-enabled" tabindex="-1">Check 3: Is the event type enabled? <a class="header-anchor" href="#check-3-is-the-event-type-enabled" aria-label="Permalink to &quot;Check 3: Is the event type enabled?&quot;">​</a></h2><p>For service-specific webhooks (GitHub, GitLab, etc.), the connection may be filtering events.</p><p>For GitHub, check which hooks are enabled:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!gh help</span></span></code></pre></div><p>Or check the room state event directly. The <code>enableHooks</code> array controls which events produce messages. For example, <code>push</code> events are disabled by default for GitHub.</p><h2 id="check-4-is-hookshot-connected-to-the-homeserver" tabindex="-1">Check 4: Is hookshot connected to the homeserver? <a class="header-anchor" href="#check-4-is-hookshot-connected-to-the-homeserver" aria-label="Permalink to &quot;Check 4: Is hookshot connected to the homeserver?&quot;">​</a></h2><p>Check hookshot&#39;s logs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Docker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hookshot</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;error\\|appservice\\|homeserver\\|ready&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Log message</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Homeserver is ready</code></td><td>Connection OK</td></tr><tr><td><code>Failed to connect to homeserver</code></td><td>Can&#39;t reach homeserver — check <code>bridge.url</code> in config</td></tr><tr><td><code>Homeserver returned 403</code></td><td>Registration rejected — check <code>registration.yaml</code> matches on both sides</td></tr><tr><td><code>Error sending event</code></td><td>Hookshot receives webhooks but can&#39;t send to Matrix</td></tr></tbody></table><h2 id="check-5-is-the-message-being-transformed-away" tabindex="-1">Check 5: Is the message being transformed away? <a class="header-anchor" href="#check-5-is-the-message-being-transformed-away" aria-label="Permalink to &quot;Check 5: Is the message being transformed away?&quot;">​</a></h2><p>For generic webhooks with a transformation function, the function may return <code>null</code> (which suppresses the message) or throw an error silently.</p><p>Test with a minimal transformation:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Temporary: pass everything through</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { version: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;v2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, plain: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stringify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(data) };</span></span></code></pre></div><p>If messages appear with this transformation, the issue is in your transformation function.</p><h2 id="check-6-service-specific-webhook-verification" tabindex="-1">Check 6: Service-specific webhook verification <a class="header-anchor" href="#check-6-service-specific-webhook-verification" aria-label="Permalink to &quot;Check 6: Service-specific webhook verification&quot;">​</a></h2><h3 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub&quot;">​</a></h3><ol><li>In your GitHub App settings, check &quot;Recent Deliveries&quot; — does GitHub show successful delivery?</li><li>Verify the webhook URL ends with <code>/github/webhook</code> (not <code>/github/</code> or <code>/webhook</code>)</li><li>Verify the webhook secret in GitHub App matches <code>github.webhook.secret</code> in config</li><li>Check that the GitHub App is installed on the target repository/organization</li></ol><h3 id="gitlab" tabindex="-1">GitLab <a class="header-anchor" href="#gitlab" aria-label="Permalink to &quot;GitLab&quot;">​</a></h3><ol><li>In your GitLab project → Settings → Webhooks, check &quot;Recent events&quot;</li><li>Verify the webhook URL points to <code>/gitlab</code></li><li>Verify the secret token matches your config</li></ol><h3 id="generic-webhooks" tabindex="-1">Generic webhooks <a class="header-anchor" href="#generic-webhooks" aria-label="Permalink to &quot;Generic webhooks&quot;">​</a></h3><ol><li>Verify the hookId in the URL matches an active webhook — send <code>!hookshot webhook list</code> in the room</li><li>Check if the webhook has expired (<code>expirationDate</code> in the connection config)</li></ol><h2 id="check-7-check-metrics" tabindex="-1">Check 7: Check metrics <a class="header-anchor" href="#check-7-check-metrics" aria-label="Permalink to &quot;Check 7: Check metrics&quot;">​</a></h2><p>If you have Prometheus monitoring:</p><table tabindex="0"><thead><tr><th>Metric</th><th>What to check</th></tr></thead><tbody><tr><td><code>hookshot_webhooks_received_total</code></td><td>Incrementing when you send webhooks?</td></tr><tr><td><code>hookshot_matrix_messages_sent_total</code></td><td>Incrementing?</td></tr><tr><td><code>hookshot_matrix_messages_failed_total</code></td><td>Incrementing? (problem sending to Matrix)</td></tr></tbody></table><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><ol><li>Set <code>logging.level: debug</code> and send a test webhook</li><li>Look for the webhook request in logs — you should see the full routing path</li><li>If the webhook appears in logs but no message is sent, the issue is in the connection handler</li><li>If no log entry appears, the request isn&#39;t reaching hookshot (firewall, reverse proxy, or port issue)</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./">Troubleshooting Index</a> — All troubleshooting pages</li><li><a href="./../integrations/generic-webhooks">Generic Webhooks</a> — Webhook setup and configuration</li><li><a href="./../integrations/github">GitHub Integration</a> — GitHub-specific setup</li><li><a href="./../reference/metrics">Reference: Metrics</a> — Prometheus metrics</li></ul>`,43)])])}const g=t(a,[["render",h]]);export{p as __pageData,g as default};
